<script setup>
import BudgetCharts from './BudgetCharts.vue';
import { ref, computed, onMounted, onBeforeUnmount, watch, nextTick } from 'vue';
const year=ref(new Date().getFullYear()),newYear=ref(new Date().getFullYear()+1),years=ref([]),rows=ref([]),type=ref(''),department=ref(''),status=ref(''),search=ref(''),error=ref(''),busy=ref(false),selected=ref(null),editing=ref(null),user=ref(null),note=ref(''),actual=ref(0),showForm=ref(false);
const tab=ref('dashboard'),settings=ref({users:[],eligible:[],assignments:[]}),settingForm=ref({requester:'',approver:''}),showSettings=ref(false),settingsDialog=ref(null),notice=ref(''),showImport=ref(false),importDialog=ref(null),importFile=ref(null);
watch(showImport,async visible=>{await nextTick();if(visible)importDialog.value?.showModal();});
watch(showSettings,async visible=>{await nextTick();if(visible)settingsDialog.value?.showModal();});
const statuses=computed(()=>Object.entries(labels).map(([key,label])=>({key,label,count:rows.value.filter(r=>r.status===key).length})));
const pending=computed(()=>rows.value.filter(r=>['submitted','reviewed'].includes(r.status)&&(r.approver===user.value?.username||!r.approver&&['admin','approver'].includes(user.value?.role))));
const byDepartment=computed(()=>departments.value.map(name=>{const items=rows.value.filter(r=>r.department===name);return {name,count:items.length,amount:items.reduce((sum,r)=>sum+r.amount,0),actual:items.reduce((sum,r)=>sum+r.actual,0)};}));
async function loadSettings(){settings.value=await api('/settings');}
function configure(requester='',approver=''){settingForm.value={requester,approver};showSettings.value=true;}
function saveSettings(){run(async()=>{settings.value=await api('/settings','PUT',settingForm.value);showSettings.value=false;notice.value='Pengaturan approver disimpan.';});}
async function importExcel(){const file=importFile.value;if(!file)return;await run(async()=>{const body=new FormData();body.append('file',file);body.append('year',year.value);const response=await fetch('/api/budget/import',{method:'POST',body});const result=await response.json();if(!response.ok)throw new Error(result.error||'Impor gagal');await load();tab.value='list';notice.value=result.count+' pengajuan diimpor sebagai draft.';showImport.value=false;importFile.value=null;});}
const blank=()=>({title:'',department:'',type:'CAPEX',amount:0,purpose:''});
const form=ref(blank()),formDialog=ref(null),detailDialog=ref(null);
watch(showForm,async visible=>{await nextTick();if(visible)formDialog.value?.showModal();});
watch(selected,async record=>{await nextTick();if(record&&!detailDialog.value?.open)detailDialog.value?.showModal();});
const actionLabels={submitted:'Ajukan anggaran',reviewed:'Selesaikan review',approved:'Setujui anggaran',rejected:'Tolak pengajuan',realizing:'Mulai realisasi',completed:'Selesaikan realisasi',draft:'Kembalikan ke draft'};
const nextStep=computed(()=>{if(!selected.value)return '';const r=selected.value;if(!can('update'))return 'Anda memiliki akses baca. Proses dilanjutkan oleh pengaju atau approver yang memiliki hak ubah Anggaran.';if(['submitted','reviewed'].includes(r.status))return 'Menunggu '+(r.status==='submitted'?'review':'persetujuan')+' oleh '+(r.approver||'admin atau approver selain pengaju')+'. Pengaju tidak dapat menyetujui pengajuannya sendiri.';return {draft:'Periksa rincian, lalu klik Ajukan anggaran untuk mengirim ke tahap review.',rejected:'Lihat alasan penolakan pada riwayat, kembalikan ke draft, perbaiki rincian, lalu ajukan kembali.',approved:'Anggaran disetujui. Pengaju atau admin dapat memulai realisasi.',realizing:'Isi total realisasi, lalu klik Selesaikan realisasi.',completed:'Proses anggaran selesai. Detail dan riwayat tetap tersedia.'}[r.status];});
const labels={draft:'Draft',submitted:'Diajukan',reviewed:'Ditinjau',approved:'Disetujui',rejected:'Ditolak',realizing:'Realisasi',completed:'Selesai'};
const flow={draft:['submitted'],submitted:['reviewed','rejected'],reviewed:['approved','rejected'],approved:['realizing'],rejected:['draft'],realizing:['completed'],completed:[]};
const can=action=>!!user.value?.actions?.budget?.[action]||user.value?.role==='admin';
const owns=r=>r.requesterId===String(user.value?.username)||user.value?.role==='admin';
const actions=computed(()=>selected.value&&can('update')?(flow[selected.value.status]||[]).filter(s=>['reviewed','approved','rejected'].includes(s)?(selected.value.approver?selected.value.approver===user.value?.username:['admin','approver'].includes(user.value?.role))&&selected.value.requesterId!==String(user.value?.username):owns(selected.value)):[]);
const departments=computed(()=>[...new Set(rows.value.map(r=>r.department))].sort());
const filtered=computed(()=>rows.value.filter(r=>(!type.value||r.type===type.value)&&(!department.value||r.department===department.value)&&(!status.value||(status.value==='pending'?['submitted','reviewed'].includes(r.status):r.status===status.value))&&[r.title,r.department,r.requester].join(' ').toLowerCase().includes(search.value.toLowerCase())));
const totals=computed(()=>['CAPEX','OPEX'].map(kind=>{const items=rows.value.filter(r=>r.type===kind);return {kind,requested:items.reduce((s,r)=>s+r.amount,0),approved:items.filter(r=>['approved','realizing','completed'].includes(r.status)).reduce((s,r)=>s+r.amount,0),actual:items.reduce((s,r)=>s+r.actual,0)};}));
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:2}).format(n);
async function api(path='',method='GET',body){const response=await fetch('/api/budget'+path,{method,headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Permintaan gagal');return result;}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function load(){const result=await api('?year='+year.value);years.value=result.years;rows.value=result.requests;selected.value=selected.value?rows.value.find(r=>r.id===selected.value.id)||null:null;}
function open(){run(async()=>{user.value=await (await fetch('/api/auth/me')).json();await load();if(user.value.role==='admin')await loadSettings();});}
function chartFilter(filter){search.value='';type.value=filter.type||'';department.value=filter.department||'';status.value=filter.pending?'pending':filter.status||'';tab.value='list';}
function detail(record){selected.value=record;note.value='';actual.value=record.actual;}
function edit(record=null){selected.value=null;editing.value=record?.id||null;form.value=record?{title:record.title,department:record.department,type:record.type,amount:record.amount,purpose:record.purpose}:blank();showForm.value=true;}
function save(){run(async()=>{const saved=await api(editing.value?'/requests/'+editing.value:'/requests',editing.value?'PUT':'POST',{...form.value,year:year.value});showForm.value=false;await load();detail(rows.value.find(r=>r.id===saved.id)||saved);});}
function transition(target){run(async()=>{await api('/requests/'+selected.value.id,'PUT',{status:target,note:note.value,actual:actual.value});note.value='';await load();});}
onMounted(()=>window.addEventListener('budget-open',open));onBeforeUnmount(()=>window.removeEventListener('budget-open',open));
</script>

<template>
  <section id="budgetView" class="view budget-view">
    <div class="page-heading"><div><p class="eyebrow">PERENCANAAN & REALISASI TAHUNAN</p><h2>Anggaran</h2><p class="lede">Kelola pengajuan CAPEX dan OPEX, bagian pengaju, persetujuan, dan realisasinya per tahun.</p></div><button v-if="can('create') && years.includes(Number(year))" class="button button-accent" :disabled="busy" @click="edit()">+ Pengajuan baru</button></div>
    <div class="risk-management-tabs" role="tablist" aria-label="Anggaran"><button v-for="item in [{key:'dashboard',label:'Dashboard'},{key:'list',label:'Daftar Anggaran'},{key:'settings',label:'Pengaturan Approver'}].filter(t=>t.key!=='settings'||user?.role==='admin')" :key="item.key" class="button" :class="tab===item.key?'button-accent':'button-quiet'" role="tab" :aria-selected="tab===item.key" :aria-controls="'budget-'+item.key" @click="tab=item.key">{{item.label}}</button></div>
    <p v-if="notice" class="save-state" role="status">{{notice}}</p>
    <p v-if="error" class="budget-error" role="alert">{{error}}</p><p v-if="busy" role="status">Memproses anggaran…</p>
    <div class="assessment-year-toolbar budget-toolbar"><label>Tahun anggaran <select v-model.number="year" :disabled="busy" @change="selected=null;showForm=false;run(load)"><option v-if="!years.includes(Number(year))" :value="year">{{year}} (belum dibuat)</option><option v-for="y in years" :key="y" :value="y">{{y}}</option></select></label><form v-if="can('create')" @submit.prevent="run(async()=>{await api('/years','POST',{year:newYear});year=Number(newYear);selected=null;showForm=false;await load();})"><label>Tahun baru <input v-model.number="newYear" type="number" min="2000" max="2200" required></label><button class="button button-quiet" :disabled="busy">Buat tahun</button></form><button class="button button-quiet" :disabled="busy" @click="run(load)">Muat ulang</button></div>
    <div class="budget-flow" aria-label="Alur pengajuan"><span>Draft</span> → <span>Diajukan</span> → <span>Ditinjau</span> → <span>Disetujui</span> → <span>Realisasi</span> → <span>Selesai</span><small>Pengajuan dapat ditolak saat review/persetujuan dan dikembalikan ke draft. Review/persetujuan dilakukan oleh approver yang ditetapkan untuk pengguna pengaju.</small></div>
    <div v-if="tab==='dashboard'" id="budget-dashboard" role="tabpanel"><BudgetCharts :rows="rows" :year="Number(year)" @filter="chartFilter" /><div class="budget-cards"><article class="insight-panel" v-for="t in totals" :key="t.kind"><h3>{{t.kind}} · {{year}}</h3><p>Pengajuan <strong>{{money(t.requested)}}</strong></p><p>Disetujui <strong>{{money(t.approved)}}</strong></p><p>Realisasi <strong>{{money(t.actual)}}</strong></p><p>Sisa disetujui <strong>{{money(t.approved-t.actual)}}</strong></p></article></div>
    <div class="rd-kpis"><button v-for="item in statuses" :key="item.key" class="button button-quiet" @click="status=item.key;tab='list'">{{item.label}}: {{item.count}}</button></div><article class="insight-panel budget-panel"><h3>Menunggu tindakan Anda ({{pending.length}})</h3><p v-if="!pending.length">Tidak ada pengajuan yang menunggu review atau persetujuan Anda.</p><div v-for="r in pending" :key="r.id" class="budget-toolbar"><span>{{r.title}} &middot; {{r.department}} &middot; {{money(r.amount)}}</span><button class="button button-quiet" @click="detail(r)">Detail & alur</button></div></article><div class="excel-wrap"><table class="excel-table"><thead><tr><th>Bagian pengaju</th><th>Jumlah pengajuan</th><th>Nilai pengajuan</th><th>Realisasi</th></tr></thead><tbody><tr v-for="d in byDepartment" :key="d.name"><td>{{d.name}}</td><td>{{d.count}}</td><td>{{money(d.amount)}}</td><td>{{money(d.actual)}}</td></tr><tr v-if="!byDepartment.length"><td colspan="4">Belum ada pengajuan pada tahun ini.</td></tr></tbody></table></div></div>
    <div v-if="tab==='settings'&&user?.role==='admin'" id="budget-settings" role="tabpanel"><article class="insight-panel budget-panel"><div class="section-heading"><h3>Approver per pengguna</h3><button class="button button-accent" :disabled="busy" @click="configure()">+ Atur approver</button></div><p>Approver harus memiliki hak ubah Anggaran dan berbeda dari pengaju. Pengaturan berlaku saat pengajuan dikirim; pengajuan yang sedang diproses tetap menggunakan approver yang sudah dicatat.</p><div class="excel-wrap"><table class="excel-table"><thead><tr><th>Pengguna / pengaju</th><th>Approver</th><th>Aksi</th></tr></thead><tbody><tr v-for="u in settings.users" :key="u.username"><td>{{u.fullName||u.username}} ({{u.username}})</td><td>{{settings.assignments.find(a=>a.requester===u.username)?.approver||'Belum diatur'}}</td><td><button class="button button-quiet" :disabled="busy" @click="configure(u.username,settings.assignments.find(a=>a.requester===u.username)?.approver||'')">Atur approver</button></td></tr></tbody></table></div></article></div>
    <dialog v-if="showSettings" ref="settingsDialog" class="certification-modal risk-management-modal budget-dialog" @cancel="showSettings=false"><form class="risk-register-form" @submit.prevent="saveSettings"><h3>Atur approver pengguna</h3><p v-if="error" class="budget-error" role="alert">{{error}}</p><div class="csf-form-grid risk-register-grid"><label>Pengaju<select v-model="settingForm.requester" required><option value="">Pilih pengguna</option><option v-for="u in settings.users" :key="u.username" :value="u.username">{{u.fullName||u.username}} ({{u.username}})</option></select></label><label>Approver<select v-model="settingForm.approver" required><option value="">Pilih approver</option><option v-for="u in settings.users.filter(u=>settings.eligible.includes(u.username)&&u.username!==settingForm.requester)" :key="u.username" :value="u.username">{{u.fullName||u.username}} ({{u.username}})</option></select></label></div><div class="csf-form-actions"><button class="button button-accent" :disabled="busy">Simpan pengaturan</button><button type="button" class="button button-quiet" :disabled="busy" @click="showSettings=false">Batal</button></div></form></dialog>
    <dialog v-if="showImport" ref="importDialog" class="certification-modal risk-management-modal budget-dialog" @cancel="showImport=false"><form class="risk-register-form" @submit.prevent="importExcel"><h3>Impor anggaran &middot; {{year}}</h3><p v-if="error" class="budget-error" role="alert">{{error}}</p><p>Impor menambahkan draft baru atas nama akun Anda. Status dan persetujuan dari file tidak akan diimpor. Maksimal 1000 baris dan 2 MB.</p><label>File Excel (.xlsx)<input type="file" accept=".xlsx" required :disabled="busy" @change="importFile=$event.target.files?.[0]||null"></label><div class="csf-form-actions"><button class="button button-accent" :disabled="busy||!importFile">Impor sebagai draft</button><button type="button" class="button button-quiet" :disabled="busy" @click="showImport=false">Batal</button><a class="button button-quiet" href="/api/budget/excel?template=1">Unduh template</a></div></form></dialog>
    <dialog v-if="showForm" ref="formDialog" class="certification-modal risk-management-modal budget-dialog" @cancel="showForm=false"><form class="risk-register-form" @submit.prevent="save"><p v-if="error" class="budget-error" role="alert">{{error}}</p><h3>{{editing?'Edit draft':'Pengajuan baru'}} · {{year}}</h3><div class="csf-form-grid risk-register-grid"><label>Judul pengajuan<input v-model="form.title" required maxlength="2000"></label><label>Bagian / departemen pengaju<input v-model="form.department" list="budgetDepartments" required maxlength="2000"><datalist id="budgetDepartments"><option v-for="d in departments" :key="d" :value="d" /></datalist></label><label>Jenis<select v-model="form.type"><option>CAPEX</option><option>OPEX</option></select></label><label>Nilai anggaran (IDR)<input v-model.number="form.amount" type="number" min="0" max="1000000000000" step="0.01" required></label><label>Tujuan / justifikasi<textarea v-model="form.purpose" required maxlength="2000" rows="3"></textarea></label></div><div class="csf-form-actions"><button class="button button-accent" :disabled="busy">Simpan draft</button><button type="button" class="button button-quiet" :disabled="busy" @click="showForm=false">Batal</button></div></form></dialog>
    <div v-if="tab==='list'" id="budget-list" role="tabpanel"><div class="budget-toolbar"><a class="button button-quiet" :href="'/api/budget/excel?year='+year">Ekspor Excel (semua data tahun ini)</a><a class="button button-quiet" href="/api/budget/excel?template=1">Unduh template Excel</a><button v-if="can('create')&&years.includes(Number(year))" class="button button-quiet" :disabled="busy" @click="importFile=null;showImport=true">Impor Excel</button></div><p class="muted">Impor menambahkan draft baru ke tahun yang dipilih. Gunakan template; maksimal 1000 baris dan 2 MB.</p><div class="rd-filters budget-toolbar"><input v-model="search" aria-label="Cari pengajuan" placeholder="Cari judul, pengaju, bagian…"><select v-model="type" aria-label="Filter jenis"><option value="">Semua jenis</option><option>CAPEX</option><option>OPEX</option></select><select v-model="department" aria-label="Filter bagian"><option value="">Semua bagian</option><option v-for="d in departments" :key="d">{{d}}</option></select><select v-model="status" aria-label="Filter status"><option value="">Semua status</option><option value="pending">Menunggu review / persetujuan</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select><span>{{filtered.length}} pengajuan · rekap mengikuti filter</span></div>
    <div class="excel-wrap"><table class="excel-table"><thead><tr><th>Pengajuan</th><th>Jenis</th><th>Bagian pengaju</th><th>Pengaju</th><th>Nilai</th><th>Realisasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td>{{r.title}}</td><td>{{r.type}}</td><td>{{r.department}}</td><td>{{r.requester}}</td><td>{{money(r.amount)}}</td><td>{{money(r.actual)}}</td><td>{{labels[r.status]}}</td><td><button class="button button-quiet" @click="detail(r)">Detail & alur</button><button v-if="r.status==='draft'&&can('update')&&owns(r)" class="button button-quiet" @click="edit(r)">Edit</button></td></tr><tr v-if="!filtered.length"><td colspan="8">{{years.includes(Number(year))?'Belum ada pengajuan sesuai filter.':'Buat tahun anggaran untuk mulai menambahkan CAPEX dan OPEX.'}}</td></tr></tbody></table></div>
    </div>
    <dialog v-if="selected" ref="detailDialog" class="certification-modal risk-management-modal budget-dialog" aria-labelledby="budgetDetailTitle" @cancel="selected=null"><div class="risk-register-form"><p v-if="error" class="budget-error" role="alert">{{error}}</p><p v-if="busy" role="status">Menyimpan perubahan...</p><div class="section-heading"><h3 id="budgetDetailTitle">{{selected.title}} · {{labels[selected.status]}}</h3><button class="button button-quiet" :disabled="busy" @click="selected=null">Tutup detail</button></div><p>{{selected.type}} · {{selected.year}} · {{selected.department}} · {{selected.requester}}</p><p class="budget-purpose">{{selected.purpose}}</p><p>Approver: <strong>{{selected.approver||'Ditentukan saat pengajuan dikirim'}}</strong></p><p>Anggaran: <strong>{{money(selected.amount)}}</strong> · Realisasi: <strong>{{money(selected.actual)}}</strong></p><p class="insight-panel" role="status">{{nextStep}}</p><button v-if="selected.status==='draft'&&can('update')&&owns(selected)" class="button button-quiet" :disabled="busy" @click="edit(selected)">Edit draft</button><div v-if="actions.length" class="budget-panel"><label>Catatan / alasan penolakan<textarea v-model="note" maxlength="2000" rows="2"></textarea></label><label v-if="selected.status==='realizing'">Total realisasi (IDR)<input v-model.number="actual" type="number" min="0" :max="selected.amount" step="0.01"></label><div class="csf-form-actions"><button v-for="target in actions" :key="target" class="button button-accent" :disabled="busy" @click="transition(target)">{{actionLabels[target]}}</button></div></div><h4>Riwayat pengajuan</h4><ol><li v-for="(h,i) in selected.history" :key="i"><strong>{{labels[h.status]}}</strong> · {{h.actor}} · {{new Date(h.at).toLocaleString('id-ID')}}<p v-if="h.note">{{h.note}}</p></li></ol></div></dialog>
  </section>
</template>

<style scoped>
.budget-dialog label{display:grid;gap:6px}.budget-dialog textarea{width:100%}.budget-dialog{width:min(850px,94vw);max-height:90vh;overflow:auto;color:var(--ink);background:var(--surface,#fff)}.budget-dialog::backdrop{background:rgba(19,35,42,.5)}.budget-toolbar,.budget-toolbar form{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.budget-toolbar{margin:18px 0}.budget-view label{display:grid;gap:6px}.budget-view input,.budget-view select,.budget-view textarea{padding:10px;border:1px solid var(--line);border-radius:7px;background:var(--surface,#fff);color:var(--ink);font:inherit;max-width:100%}.budget-toolbar input[type=number]{width:110px}.budget-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin:20px 0}.budget-cards article,.budget-panel,.budget-flow{padding:20px;border:1px solid var(--line);border-radius:12px;background:var(--surface,#fff)}.budget-cards p{display:flex;justify-content:space-between;gap:12px}.budget-panel{margin:20px 0}.budget-panel textarea{width:100%}.budget-flow{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.budget-flow span{font-weight:700;color:var(--green)}.budget-flow small{flex-basis:100%;color:var(--muted)}.budget-error{padding:12px;color:#b42318;background:#fee2e2;border-radius:8px}.budget-purpose{white-space:pre-wrap}.budget-panel li{padding:8px 0;border-bottom:1px solid var(--line)}:global(html[data-theme=dark]) .budget-view{--surface:#19272d;--ink:#e1eae4;--line:#40534f} @media(max-width:700px){.budget-cards{grid-template-columns:1fr}.budget-cards p{flex-wrap:wrap}.budget-toolbar>*{max-width:100%}}
</style>
